def gen(rng):
    def fmt(pts):
        return str(len(pts)) + '\n' + '\n'.join(f'{x} {y}' for x, y in pts)
    def distinct(n, lo, hi):
        s = set()
        while len(s) < n:
            s.add((rng.randint(lo, hi), rng.randint(lo, hi)))
        l = sorted(s)
        rng.shuffle(l)
        return l
    tests = [fmt([(0, 0)]), fmt([(0, 0), (10**6, -10**6)]), fmt([(-10**6, -10**6), (10**6, 10**6), (-10**6, 10**6), (10**6, -10**6)]),
             fmt([(i, 0) for i in range(6)]), fmt([(0, 0), (0, 1), (1, 0), (1, 1), (2, 2)])]
    for n in (2, 3, 4, 5, 6):
        for hi in (2, 5, 20, 10**6):
            for _ in range(2):
                if (2 * hi + 1) ** 2 >= n:
                    tests.append(fmt(distinct(n, -hi, hi)))
    N = 1000
    tests.append(fmt(distinct(N, -10**6, 10**6)))
    tests.append(fmt(distinct(N, -40, 40)))
    cl = set()
    while len(cl) < N:
        cx, cy = rng.choice([-10**6, 10**6]), rng.choice([-10**6, 10**6])
        dx, dy = rng.randint(0, 300), rng.randint(0, 300)
        cl.add((cx - dx if cx > 0 else cx + dx, cy - dy if cy > 0 else cy + dy))
    cl = sorted(cl)
    rng.shuffle(cl)
    tests.append(fmt(cl))
    tests.append(fmt([(i * 1000 - 500000, 0) for i in range(N)]))
    return tests
